use crate::{Error, Instruction, parse_rules};

/// Lower version-1 rule instructions to a Rust module using the native runtime.
/// The result is valid Rust source; pinned rustfmt supplies artifact formatting.
pub fn generate(input: &str) -> Result<String, Error> {
    let rules = parse_rules(input)?;
    let mut source = String::from(
        "// Generated by bootstrap-codegen. Do not edit by hand.\n\
         use bootstrap_executor::{Error, runtime};\n\
         use serde_json::Value;\n\n\
         pub fn execute(input: &str) -> Result<i64, Error> {\n\
             runtime::concrete(evaluate(&runtime::program(input)?)?)\n\
         }\n\n\
         fn evaluate(node: &Value) -> Result<runtime::Value, Error> {\n\
             match runtime::kind(node)? {\n",
    );
    // BTreeMap iteration makes dispatch order independent of JSON key order.
    for (kind, rule) in rules.rules {
        source.push_str(&format!("{kind:?} => {},\n", instruction(&rule.result)));
    }
    source.push_str(
        "kind => Err(Error::MissingRule { kind: kind.to_string() }),\n\
             }\n\
         }\n",
    );
    Ok(source)
}

fn instruction(op: &Instruction) -> String {
    match op {
        Instruction::Int {} => "Ok::<_, Error>(runtime::Value::Int)".to_string(),
        Instruction::LowerBound { value } => {
            format!("runtime::lower_bound(({})?)", instruction(value))
        }
        Instruction::UpperBound { value } => {
            format!("runtime::upper_bound(({})?)", instruction(value))
        }
        // Debug formatting emits escaped Rust string literals, not raw code.
        Instruction::Field { field } => format!("runtime::integer(node, {field:?})"),
        Instruction::Evaluate { field } => format!("evaluate(runtime::field(node, {field:?})?)"),
        Instruction::Negate { value } => {
            format!("runtime::negate(({})?)", instruction(value))
        }
        Instruction::Sum { left, right } => format!(
            "runtime::sum(({})?, ({})?)",
            instruction(left),
            instruction(right)
        ),
        Instruction::Difference { left, right } => format!(
            "runtime::difference(({})?, ({})?)",
            instruction(left),
            instruction(right)
        ),
        Instruction::Product { left, right } => format!(
            "runtime::product(({})?, ({})?)",
            instruction(left),
            instruction(right)
        ),
        Instruction::Unify { left, right } => format!(
            "runtime::unify(({})?, ({})?)",
            instruction(left),
            instruction(right)
        ),
    }
}
